function q({registerIndicator:x,sourceValues:A,nulls:g}){x({id:"oa-macd",name:"Moving Average Convergence Divergence (MACD)",category:"Momentum",placement:"pane",inputs:[{key:"fastLength",type:"number",label:"Fast Length",default:12,min:1,max:5e3,step:1},{key:"slowLength",type:"number",label:"Slow Length",default:26,min:2,max:5e3,step:1},{key:"signalLength",type:"number",label:"Signal Length",default:9,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"histogram",type:"column",title:"Histogram",style:{color:"#4caf50"},colorBy:({value:s})=>s>=0?"#4caf50":"#ff5252"},{key:"macd",type:"line",title:"MACD",style:{color:"#2196f3",lineWidth:2}},{key:"signal",type:"line",title:"Signal",style:{color:"#ff5252",lineWidth:2}}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86"}],calc(s,i){const C=Math.max(1,Math.floor(Number(i.fastLength)||12)),v=Math.max(2,Math.floor(Number(i.slowLength)||26)),D=Math.max(1,Math.floor(Number(i.signalLength)||9)),W=A(s,i.source??"close"),c=s.length,b=new Array(c).fill(NaN),S=new Array(c).fill(NaN),d=new Array(c).fill(NaN),w=2/(C+1),L=2/(v+1),u=2/(D+1),B=1-w,H=1-L,Z=1-u;let N=!0,h=1,f=1,y=1,t=0,l=0,e=0,n=0,o=0,r=0;for(let a=0;a<c;a++){const p=W[a];if(!Number.isFinite(p))continue;if(t=w*(p-t)+t,l=L*(p-l)+l,N){h*=B,f*=H,y*=Z;const m=1/(1-h),M=1/(1-f),k=1/(1-y);n=Number.isFinite(m)?m*t:t,o=Number.isFinite(M)?M*l:l;const j=n-o;e=u*(j-e)+e,r=Number.isFinite(k)?k*e:e,N=h>1e-10||f>1e-10||y>1e-10}else{n=t,o=l;const m=n-o;e=u*(m-e)+e,r=e}const F=n-o;b[a]=F,S[a]=r,d[a]=F-r}return{macd:g(b),signal:g(S),histogram:g(d)}}})}export{q as default};
